import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"23、【剝】 坤下艮上","description":"子夏易傳 - 23、【剝】 坤下艮上","frontmatter":{"title":"23、【剝】 坤下艮上","description":"子夏易傳 - 23、【剝】 坤下艮上"},"headers":[],"relativePath":"classics/zixia/025.md","filePath":"classics/zixia/025.md"}'),i={name:"classics/zixia/025.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_23、【剝】-坤下艮上" tabindex="-1">23、【剝】 坤下艮上 <a class="header-anchor" href="#_23、【剝】-坤下艮上" aria-label="Permalink to “23、【剝】 坤下艮上”">​</a></h1><p>卦辭：剝，不利有攸往。</p><p>彖曰：剝，剝也。柔變剛也。不利有攸往，小人長也。順而止之觀象也。君子尚消息盈虛，天行也。</p><p>子夏：剝，柔乘剛也。君子之道僅存也。何所往哉，順其時止而止之，可以觀其象，而適其變也。夫道，無定體也。唯時行之，消而息之，盈而虛之，天之道也。君子之尚也。故當其道往，而不吝焉。應其時而不自得焉。</p><p>象曰：山附於地，剝。上以厚下，安宅。</p><p>子夏：山髙也，地下也，下剝上則山附於地也。故君不可以制下，則厚順於下，因而安宅之，不敢遷也。</p><p>初六，剝床以足蔑，貞兇。</p><p>象曰：剝床以足，以滅下也。</p><p>子夏：床，人之所安也。剝之以足，滅下之道。潛而剝之，猶未見也。無陽自此始矣。兇之道也。</p><p>六二，剝床以辨蔑，貞兇。</p><p>象曰：剝床以辨，未有與也。</p><p>子夏：剝以漸長，小人漸得位也。至剝其床，剝道見而可辨也。無正而得位，誰與之哉，兇之道也。</p><p>六三，剝之無咎。</p><p>象曰：剝之無咎，失上下也。</p><p>子夏：群小剝上，已獨應之，無咎者也。猶應離群失眾之趨也。</p><p>六四，剝床以膚，兇。</p><p>象曰：剝床以膚，切近災也。</p><p>子夏：剝至上，體過床以及膚，近於災也。兇，其危也。</p><p>六五，貫魚以宮人寵。無不利。</p><p>象曰：以宮人寵，終無尤也。</p><p>子夏：剝上於五，為剝之主，能得其中。上承於陽，反止群小，群小由之貫魚。寵以宮人，不害外正，何不利焉。則終無尤矣。</p><p>上九，碩果不食，君子得輿小人，剝廬。</p><p>象曰：君子得輿民所載也。</p><p>子夏：小人剝廬，終不可用也。極剝而保於上，大果有乎。拔不食者也。極消則息道，斯來矣。君子厚徳以藏垢也，故民所載矣。小人矜忌而偶怨也。故剝人之廬，終不可用也。復而不敵怨於剝者，君子也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
